70	// ----------------------------------------------------------------------------
71	// Node definitions: MAC/IP/UDP ports (same as in VUserMainUdp.cpp)
72	// ----------------------------------------------------------------------------
73	#define NODE1_MAC_ADDR   0xd89ef3887ec3ULL  // D8:9E:F3:88:7E:C3
74	#define NODE1_IPV4_ADDR  0xc0a81908        // 192.168.25.8
75	#define NODE1_UDP_PORT   0x0400            // UDP port 1024
76	
77	#define NODE2_MAC_ADDR   0x90324b070bd1ULL  // 90:32:4B:07:0B:D1
78	#define NODE2_IPV4_ADDR  0xc0a89801        // 192.168.152.1
79	#define NODE2_UDP_PORT   0x0401            // UDP port 1025
80	
81	#define NODE3_MAC_ADDR   0xAABBCCDDEEFFULL  // example MAC for Node3
82	#define NODE3_IPV4_ADDR  0xc0a80103        // 192.168.1.3
83	#define NODE3_UDP_PORT   0x0500            // UDP port 1280
84	
85	#define NODE4_MAC_ADDR   0x112233445566ULL  // example MAC for Node4
86	#define NODE4_IPV4_ADDR  0xc0a80104        // 192.168.1.4
87	#define NODE4_UDP_PORT   0x0501            // UDP port 1281
88	
89	static constexpr uint64_t NODE1_INIT_TICKS  = 1;
90	static constexpr uint64_t NODE3_INIT_TICKS  = 1;
91	static constexpr uint64_t NODE1_INIT_NS     = NODE1_INIT_TICKS * pcapreplay::GMII_TICK_NS;
92	static constexpr uint64_t NODE3_INIT_NS     = NODE3_INIT_TICKS * pcapreplay::GMII_TICK_NS;
93	
94	// ----------------------------------------------------------------------------
95	// VUserMain1: Node1 replays PCAP to Node2
96	// ----------------------------------------------------------------------------
97	extern "C" void VUserMain1(void) {
98	    VPrint("Node1: PCAP replay init\n");
99	    udpIpPg pUdp(1, NODE1_IPV4_ADDR, NODE1_MAC_ADDR, NODE1_UDP_PORT);
100	
101	    // Small initial idle to let the system settle
102	    for (uint64_t i = 0; i < NODE1_INIT_TICKS; ++i) {
103	        pUdp.UdpVpSendIdle(1); // ~1ms
104	    }
105	
106	    std::string in1 = Manager::GetEnvOr("PCAP_IN_1", "./tools/test_udp_rand.pcap");
107	    VPrint("Node1: replaying %s\n", in1.c_str());
108	    bool rewrite = Manager::GetEnvBool("PCAP_REWRITE", true);
109	    static pcapio::Writer tx1;
110	    std::string tx1p = Manager::GetEnvOr("PCAP_TX_OUT_1", "./output/tx_node1.pcap");
111	    try {
112	        std::filesystem::create_directories(std::filesystem::path(tx1p).parent_path());
113	    } catch(...) {}
114	    tx1.open(tx1p, pcapio::TimeRes::Nanos);
115	    std::string merge2p = Manager::GetEnvOr("PCAP_MERGE_OUT_2", "./output/merge_node2.pcap");
116	    if (!merge2p.empty() && merge2p != "0")
117	        g_merge_node2.init(merge2p);
118	    Manager::ReplayPcap(pUdp, in1.c_str(), rewrite,
119	                        NODE1_MAC_ADDR, NODE2_MAC_ADDR,
120	                        NODE1_IPV4_ADDR, NODE2_IPV4_ADDR,
121	                        (uint16_t)NODE2_UDP_PORT,
122	                        &tx1,
123	                        &g_tx_times_node2,
124	                        &g_tx_mtx_node2,
125	                        NODE1_INIT_NS,
126	                        &g_merge_node2);
127	}
128	
129	// ----------------------------------------------------------------------------
130	// VUserMain2: Node2 records to PCAP
131	// ----------------------------------------------------------------------------
132	extern "C" void VUserMain2(void) {
133	    VPrint("Node2: PCAP record init\n");
134	    udpIpPg pUdp(2, NODE2_IPV4_ADDR, NODE2_MAC_ADDR, NODE2_UDP_PORT);
135	
136	    std::string out2 = Manager::GetEnvOr("PCAP_OUT_2", "./output/node2_out.pcap");
137	    // Ensure directory exists
138	    try {
139	        std::filesystem::create_directories(std::filesystem::path(out2).parent_path());
140	    } catch(...) {}
141	    static RxRecorderCtx ctx2;
142	    if (!ctx2.writer.open(out2, pcapio::TimeRes::Nanos)) {
143	        VPrint("Node2: failed to open %s for write\n", out2.c_str());
144	    }
145	    ctx2.node_id = 2;
146	    ctx2.tx_times = &g_tx_times_node2;
147	    ctx2.tx_mtx   = &g_tx_mtx_node2;
148	    ctx2.sched_offset_ns = NODE1_INIT_NS;
149	    ctx2.min_latency_ns  = Manager::GetEnvU64("PCAP_MIN_LATENCY_NS", 0);
150	    ctx2.merge_logger    = &g_merge_node2;
151	    ctx2.local_mac = NODE2_MAC_ADDR;
152	    ctx2.local_ip  = NODE2_IPV4_ADDR;
153	    Manager::RegisterRecorder(pUdp, &ctx2);
154	    while (true)
155	        pUdp.UdpVpSendIdle(1);
156	}
157	
158	// ----------------------------------------------------------------------------
159	// VUserMain3: Node3 replays PCAP to Node4
160	// ----------------------------------------------------------------------------
161	extern "C" void VUserMain3(void) {
162	    VPrint("Node3: PCAP replay init\n");
163	    udpIpPg pUdp(3, NODE3_IPV4_ADDR, NODE3_MAC_ADDR, NODE3_UDP_PORT);
