178	    std::string merge4p = Manager::GetEnvOr("PCAP_MERGE_OUT_4", "./output/merge_node4.pcap");
179	    if (!merge4p.empty() && merge4p != "0")
180	        g_merge_node4.init(merge4p);
181	    Manager::ReplayPcap(pUdp, in3.c_str(), rewrite,
182	                        NODE3_MAC_ADDR, NODE4_MAC_ADDR,
183	                        NODE3_IPV4_ADDR, NODE4_IPV4_ADDR,
184	                        (uint16_t)NODE4_UDP_PORT,
185	                        &tx3,
186	                        &g_tx_times_node4,
