45	module tb;
46	   import dpe_pkg::*;
47	   import csr_pkg::*;
48	
49	   // Constants
50	   localparam CLK_PERIOD = 12_500;
51	   
52	   // Clock and reset signals
53	   logic clk = 0;
54	   logic rst = 1;
55	
56	   // Interfaces
57	   csr_pkg::csr__out_t from_csr;
58	   //csr_pkg::csr__in_t to_csr;
59	   dpe_if from_cpu(.clk(clk), .rst(rst));
60	   dpe_if from_eth_1(.clk(clk), .rst(rst));
61	   dpe_if from_eth_2(.clk(clk), .rst(rst));
62	   dpe_if from_eth_3(.clk(clk), .rst(rst));
63	   dpe_if from_eth_4(.clk(clk), .rst(rst));
64	   dpe_if to_cpu(.clk(clk), .rst(rst));
65	   dpe_if to_eth_1(.clk(clk), .rst(rst));
66	   dpe_if to_eth_2(.clk(clk), .rst(rst));
67	   dpe_if to_eth_3(.clk(clk), .rst(rst));
68	   dpe_if to_eth_4(.clk(clk), .rst(rst));
69	
70	   // Test data type and constants
71	   typedef logic [7:0] test_data_t [6];
72	   typedef test_data_t packet_data_t [5];
73	
74	   const packet_data_t packet_data = '{
