172	               #1ps;
173	            end
174	            from_cpu.tvalid = 0;
175	            from_cpu.tlast = 0;
176	         end
177	
178	         // Input 1 stimulus
179	         begin
180	            @(posedge clk);
181	            #1ps;
182	            from_eth_1.tvalid = 1;
183	            from_eth_1.tkeep = '1;
184	            from_eth_1.tuser_dst = DPE_ADDR_CPU;
185	            for (int i = 0; i < 4; i++) begin
186	               from_eth_1.tdata[7:0] = packet_data[1][i];
187	               from_eth_1.tlast = (i == 3);
188	               @(posedge clk);
189	               while (!from_eth_1.tready) @(posedge clk);
190	               #1ps;
