65	class MergeLogger {
66	public:
67	    bool init(const std::string& path) {
68	        if (path.empty())
69	            return false;
70	        std::lock_guard<std::mutex> lk(mtx_);
71	        if (enabled_)
72	            return true;
73	        std::filesystem::path p(path);
74	        auto parent = p.parent_path();
75	        if (!parent.empty()) {
76	            try {
77	                std::filesystem::create_directories(parent);
78	            } catch(...) {}
79	        }
80	        if (!writer_.open(path, pcapio::TimeRes::Nanos)) {
81	            VPrint("MergeLogger: failed to open %s\n", path.c_str());
82	            return false;
83	        }
84	        enabled_ = true;
85	        return true;
86	    }
87	
88	    bool enabled() const { return enabled_; }
89	
90	    void log(uint64_t ts_ns, const std::vector<uint8_t>& frame) {
91	        if (!enabled_)
92	            return;
93	        std::lock_guard<std::mutex> lk(mtx_);
94	        uint32_t ts_sec  = (uint32_t)(ts_ns / 1000000000ull);
95	        uint32_t ts_frac = (uint32_t)(ts_ns % 1000000000ull);
96	        writer_.write(ts_sec, ts_frac, frame);
97	    }
98	
99	private:
100	    pcapio::Writer writer_;
101	    bool enabled_ = false;
102	    mutable std::mutex mtx_;
103	};
