185	inline uint32_t Manager::EthCrc32(const uint8_t* data, size_t len) {
186	    uint32_t crc = 0xFFFFFFFFu;
187	    for (size_t i = 0; i < len; ++i) {
188	        crc ^= data[i];
189	        for (int j = 0; j < 8; ++j) {
190	            uint32_t mask = -(int)(crc & 1u);
191	            crc = (crc >> 1) ^ (0xEDB88320u & mask);
192	        }
193	    }
194	    return ~crc;
195	}
196	
197	inline void Manager::MacToBytes(uint64_t mac48, uint8_t* out6) {
198	    out6[0] = static_cast<uint8_t>((mac48 >> 40) & 0xFF);
199	    out6[1] = static_cast<uint8_t>((mac48 >> 32) & 0xFF);
200	    out6[2] = static_cast<uint8_t>((mac48 >> 24) & 0xFF);
201	    out6[3] = static_cast<uint8_t>((mac48 >> 16) & 0xFF);
202	    out6[4] = static_cast<uint8_t>((mac48 >> 8) & 0xFF);
203	    out6[5] = static_cast<uint8_t>(mac48 & 0xFF);
204	}
205	
206	inline uint16_t Manager::Ipv4Checksum(const uint8_t* hdr, size_t len) {
207	    uint32_t sum = 0;
208	    for (size_t i = 0; i + 1 < len; i += 2) {
209	        sum += (uint16_t)(hdr[i] << 8 | hdr[i + 1]);
210	    }
211	    if (len & 1) {
212	        sum += (uint16_t)(hdr[len - 1] << 8);
213	    }
214	    while (sum >> 16) {
215	        sum = (sum & 0xFFFF) + (sum >> 16);
216	    }
217	    return (uint16_t)(~sum);
218	}
219	
220	inline uint16_t Manager::UdpChecksumIpv4(uint32_t src_ip, uint32_t dst_ip,
221	                                         const uint8_t* udp, size_t len) {
222	    uint32_t sum = 0;
223	    auto add16 = [&](uint16_t v) { sum += v; };
224	    add16((uint16_t)(src_ip >> 16));
225	    add16((uint16_t)(src_ip & 0xFFFF));
226	    add16((uint16_t)(dst_ip >> 16));
227	    add16((uint16_t)(dst_ip & 0xFFFF));
228	    add16(0x0011);
229	    add16((uint16_t)len);
230	    for (size_t i = 0; i + 1 < len; i += 2) {
231	        add16((uint16_t)(udp[i] << 8 | udp[i + 1]));
232	    }
233	    if (len & 1) {
234	        add16((uint16_t)(udp[len - 1] << 8));
235	    }
236	    while (sum >> 16) {
237	        sum = (sum & 0xFFFF) + (sum >> 16);
238	    }
239	    uint16_t res = (uint16_t)(~sum);
240	    return res == 0 ? 0xFFFF : res;
241	}
