243	inline std::vector<uint8_t> Manager::BuildFallbackFrame(const udpIpPg::rxInfo_t &info,
244	                                                        uint64_t local_mac,
245	                                                        uint32_t local_ip) {
246	    const uint16_t eth_type = 0x0800;
247	    const uint8_t ihl_ver = 0x45;
248	    const uint8_t tos = 0x00;
249	    const uint16_t udp_len = (uint16_t)(8 + info.rx_len);
250	    const uint16_t ip_tot_len = (uint16_t)(20 + udp_len);
251	    const uint16_t id = 0x0000;
252	    const uint16_t flags_frag = 0x0000;
253	    const uint8_t ttl = 64;
254	    const uint8_t proto = 17;
255	
256	    std::vector<uint8_t> pkt;
257	    pkt.resize(14 + 20 + 8 + info.rx_len);
258	    uint8_t *p = pkt.data();
259	
260	    MacToBytes(local_mac, p + 0);
261	    MacToBytes(info.mac_src_addr, p + 6);
262	    BePut16(p + 12, eth_type);
263	
264	    p[14] = ihl_ver;
265	    p[15] = tos;
266	    BePut16(p + 16, ip_tot_len);
267	    BePut16(p + 18, id);
268	    BePut16(p + 20, flags_frag);
269	    p[22] = ttl;
270	    p[23] = proto;
271	    BePut16(p + 24, 0);
272	    BePut32(p + 26, info.ipv4_src_addr);
273	    BePut32(p + 30, local_ip);
274	    BePut16(p + 24, Ipv4Checksum(p + 14, 20));
275	
276	    BePut16(p + 34, (uint16_t)info.udp_src_port);
277	    BePut16(p + 36, (uint16_t)info.udp_dst_port);
278	    BePut16(p + 38, udp_len);
279	    BePut16(p + 40, 0);
280	
281	    std::memcpy(p + 42, info.rx_payload, info.rx_len);
282	
283	    uint16_t ucs = UdpChecksumIpv4(info.ipv4_src_addr, local_ip, p + 34, udp_len);
284	    BePut16(p + 40, ucs);
285	    return pkt;
286	}
287	
288	inline void Manager::RewriteIpv4UdpInplace(std::vector<uint8_t>& d,
289	                                           uint64_t mac_src, uint64_t mac_dst,
290	                                           uint32_t ip_src,  uint32_t ip_dst,
291	                                           uint16_t udp_dst_port) {
292	    if (d.size() < 42)
293	        return;
294	    if (!((d[12] == 0x08) && (d[13] == 0x00)))
295	        return;
296	    size_t ip_off = 14;
297	    size_t ihl = (d[ip_off] & 0x0F) * 4;
298	    if (ihl < 20 || d.size() < ip_off + ihl + 8)
299	        return;
300	    if (d[ip_off + 9] != 17)
301	        return;
302	
303	    auto wrmac = [&](size_t off, uint64_t mac) {
304	        d[off+0] = (uint8_t)((mac >> 40) & 0xFF);
305	        d[off+1] = (uint8_t)((mac >> 32) & 0xFF);
306	        d[off+2] = (uint8_t)((mac >> 24) & 0xFF);
307	        d[off+3] = (uint8_t)((mac >> 16) & 0xFF);
308	        d[off+4] = (uint8_t)((mac >> 8) & 0xFF);
309	        d[off+5] = (uint8_t)( mac        & 0xFF);
310	    };
311	    wrmac(0, mac_dst);
312	    wrmac(6, mac_src);
313	
314	    d[ip_off + 12] = (uint8_t)((ip_src >> 24) & 0xFF);
315	    d[ip_off + 13] = (uint8_t)((ip_src >> 16) & 0xFF);
316	    d[ip_off + 14] = (uint8_t)((ip_src >> 8) & 0xFF);
317	    d[ip_off + 15] = (uint8_t)( ip_src        & 0xFF);
318	
319	    d[ip_off + 16] = (uint8_t)((ip_dst >> 24) & 0xFF);
320	    d[ip_off + 17] = (uint8_t)((ip_dst >> 16) & 0xFF);
321	    d[ip_off + 18] = (uint8_t)((ip_dst >> 8) & 0xFF);
322	    d[ip_off + 19] = (uint8_t)( ip_dst        & 0xFF);
323	
324	    d[ip_off + 10] = 0; d[ip_off + 11] = 0;
325	    uint16_t ipcs = Ipv4Checksum(&d[ip_off], ihl);
326	    d[ip_off + 10] = (uint8_t)((ipcs >> 8) & 0xFF);
327	    d[ip_off + 11] = (uint8_t)( ipcs       & 0xFF);
328	
329	    size_t udp_off = ip_off + ihl;
330	    d[udp_off + 2] = (uint8_t)((udp_dst_port >> 8) & 0xFF);
331	    d[udp_off + 3] = (uint8_t)( udp_dst_port       & 0xFF);
332	
333	    d[udp_off + 6] = 0; d[udp_off + 7] = 0;
334	    uint16_t ucs = UdpChecksumIpv4(ip_src, ip_dst, &d[udp_off], d.size() - udp_off);
335	    d[udp_off + 6] = (uint8_t)((ucs >> 8) & 0xFF);
336	    d[udp_off + 7] = (uint8_t)( ucs       & 0xFF);
337	}
