366	inline uint64_t Manager::WireTicksFromFrameSize(size_t frame_body_len) {
367	    uint64_t ticks = frame_body_len;
368	    if (GetEnvBool("PCAP_TX_PREAMBLE", true)) {
369	        ticks += 8;
370	    }
371	    if (GetEnvBool("PCAP_TX_FCS", true)) {
372	        ticks += 4;
373	    }
374	    ticks += 1; // idle tick inserted between frames
375	    return ticks;
