377	
378	inline void Manager::ReplayPcap(udpIpPg &pUdp,
379	                                const char* path,
380	                                bool rewrite,
381	                                uint64_t mac_src,
382	                                uint64_t mac_dst,
383	                                uint32_t ip_src,
384	                                uint32_t ip_dst,
385	                                uint16_t udp_dst_port,
386	                                pcapio::Writer* tx_dump,
387	                                std::deque<uint64_t>* tx_times,
388	                                std::mutex* tx_mtx,
389	                                uint64_t sched_offset_ns,
390	                                MergeLogger* merge_logger) {
391	    pcapio::Reader r;
392	    if (!r.open(path)) {
393	        VPrint("PCAP: failed to open %s\n", path);
394	        return;
395	    }
396	    VPrint("PCAP: replaying %s (res=%s)\n", path,
397	           r.time_res() == pcapio::TimeRes::Nanos ? "ns" : "us");
398	
399	    bool first = true;
400	    uint64_t base_ns = 0;
401	    uint64_t waited_ticks = 0;
402	    pcapio::Reader::Packet pkt;
403	    int dbg_count = 0;
404	    while (r.next(pkt)) {
405	        uint64_t cur_ns = (r.time_res() == pcapio::TimeRes::Nanos)
406	                        ? ((uint64_t)pkt.ts_sec * 1000000000ull + pkt.ts_frac)
407	                        : ((uint64_t)pkt.ts_sec * 1000000000ull + (uint64_t)pkt.ts_frac * 1000ull);
408	        if (first) {
409	            base_ns = cur_ns;
410	            first = false;
411	        }
412	        uint64_t delta_ns = cur_ns - base_ns;
413	        uint64_t tx_abs_ns = sched_offset_ns + delta_ns;
414	        uint64_t target_ticks = TicksForNs(delta_ns);
415	        if (target_ticks > waited_ticks) {
416	            uint64_t add = target_ticks - waited_ticks;
417	            for (uint64_t i = 0; i < add; ++i) {
418	                pUdp.UdpVpSendIdle(1);
419	            }
420	            waited_ticks += add;
421	        }
422	
423	        if (dbg_count < 5) {
424	            const auto &d = pkt.data;
425	            if (d.size() >= 14) {
426	                uint16_t eth = (uint16_t)(d[12] << 8 | d[13]);
427	                VPrint("TX frame len=%u eth=0x%04X\n", (unsigned)d.size(), eth);
428	                if (eth == 0x0800 && d.size() >= 34) {
429	                    uint8_t proto = d[23];
430	                    VPrint("  IPv4 proto=%u src=%u.%u.%u.%u dst=%u.%u.%u.%u\n",
431	                           proto,
432	                           d[26], d[27], d[28], d[29],
433	                           d[30], d[31], d[32], d[33]);
434	                    if (proto == 17 && d.size() >= 42) {
435	                        uint16_t sp = (uint16_t)(d[34] << 8 | d[35]);
436	                        uint16_t dp = (uint16_t)(d[36] << 8 | d[37]);
437	                        VPrint("  UDP %u -> %u\n", sp, dp);
438	                    }
439	                }
440	            }
441	            dbg_count++;
442	        }
443	
444	        if (rewrite) {
445	            RewriteIpv4UdpInplace(pkt.data, mac_src, mac_dst, ip_src, ip_dst, udp_dst_port);
446	            if (dbg_count < 5) {
447	                const auto &d = pkt.data;
448	                VPrint("  REW: dstMAC=%02X:%02X:%02X:%02X:%02X:%02X srcMAC=%02X:%02X:%02X:%02X:%02X:%02X\n",
449	                       d[0],d[1],d[2],d[3],d[4],d[5], d[6],d[7],d[8],d[9],d[10],d[11]);
450	                if (d.size() >= 42) {
451	                    VPrint("  REW: src=%u.%u.%u.%u dst=%u.%u.%u.%u dport=%u\n",
452	                           d[26], d[27], d[28], d[29], d[30], d[31], d[32], d[33], (unsigned)((d[36]<<8)|d[37]));
453	                }
454	            }
455	        }
456	
457	        if (tx_dump && tx_dump->good()) {
458	            static uint32_t tns = 0;
459	            tx_dump->write(0, tns, pkt.data);
460	            tns += 1000;
461	        }
462	
463	        if (merge_logger && merge_logger->enabled()) {
464	            merge_logger->log(tx_abs_ns, pkt.data);
465	        }
466	
467	        if (tx_times && tx_mtx) {
468	            std::lock_guard<std::mutex> lk(*tx_mtx);
469	            tx_times->push_back(tx_abs_ns);
470	        }
471	
472	        bool add_preamble = GetEnvBool("PCAP_TX_PREAMBLE", true);
473	        bool add_fcs      = GetEnvBool("PCAP_TX_FCS",      true);
474	        std::vector<uint8_t> tx;
475	        tx.reserve((add_preamble?8:0) + pkt.data.size() + (add_fcs?4:0));
476	        if (add_preamble) {
477	            for (int i = 0; i < 7; ++i) {
478	                tx.push_back(0x55);
479	            }
480	            tx.push_back(0xD5);
481	        }
482	        tx.insert(tx.end(), pkt.data.begin(), pkt.data.end());
483	        if (add_fcs) {
484	            uint32_t fcs = EthCrc32(pkt.data.data(), pkt.data.size());
485	            tx.push_back((uint8_t)(fcs & 0xFF));
486	            tx.push_back((uint8_t)((fcs >> 8) & 0xFF));
487	            tx.push_back((uint8_t)((fcs >> 16) & 0xFF));
488	            tx.push_back((uint8_t)((fcs >> 24) & 0xFF));
489	        }
490	        if (dbg_count < 5) {
491	            VPrint("  TX built len=%u (preamble=%u fcs=%u)\n", (unsigned)tx.size(), add_preamble?1:0, add_fcs?1:0);
492	        }
493	
494	        const uint32_t len = (uint32_t)tx.size();
495	        std::vector<uint32_t> frame(len);
496	        for (uint32_t i = 0; i < len; ++i) {
497	            frame[i] = tx[i];
498	        }
499	        pUdp.UdpVpSendRawEthFrame(frame.data(), len);
500	        waited_ticks += (uint64_t)len + 1;
501	    }
502	    while (true)
503	        pUdp.UdpVpSendIdle(1);
504	}
505	
506	inline void Manager::RegisterRecorder(udpIpPg &pUdp, RxRecorderCtx* ctx) {
507	    pUdp.registerUsrRxCbFunc(RxRecordCallback, ctx);
508	}
509	
510	inline void Manager::RxRecordCallback(udpIpPg::rxInfo_t info, void* hdl) {
511	    auto *ctx = reinterpret_cast<RxRecorderCtx*>(hdl);
512	    if (!ctx)
513	        return;
514	
515	    uint32_t ticks = 0;
516	    VRead(udpVProc::TICKS_ADDR, &ticks, true, (int)ctx->node_id);
517	    if (!ctx->started) {
518	        ctx->started    = true;
519	        ctx->last_tick  = ticks;
520	    }
521	    if (ticks < ctx->last_tick) {
522	        ctx->tick_wraps++;
523	    }
524	    ctx->last_tick = ticks;
525	    uint64_t rx_ticks64 = (ctx->tick_wraps << 32) | (uint64_t)ticks;
526	    uint64_t ts_ns_abs  = rx_ticks64 * GMII_TICK_NS;
527	
528	    uint64_t tx_sched_abs = ctx->sched_offset_ns;
529	    if (ctx->tx_times && ctx->tx_mtx) {
530	        std::lock_guard<std::mutex> lk(*ctx->tx_mtx);
531	        if (!ctx->tx_times->empty()) {
532	            tx_sched_abs = ctx->tx_times->front();
533	            ctx->tx_times->pop_front();
534	        }
535	    }
536	
537	    uint64_t min_ts = tx_sched_abs + ctx->min_latency_ns;
538	
539	    std::vector<uint8_t> frame = BuildFallbackFrame(info, ctx->local_mac, ctx->local_ip);
540	
541	    uint64_t frame_ticks = WireTicksFromFrameSize(frame.size());
542	    uint64_t frame_ns = frame_ticks * GMII_TICK_NS;
543	    uint64_t ts_ns_start = ts_ns_abs;
544	    if (ts_ns_start >= frame_ns) {
545	        ts_ns_start -= frame_ns;
546	    }
547	    if (ts_ns_start < min_ts) {
548	        ts_ns_start = min_ts;
549	    }
550	
551	    VPrint("RX rec: len=%u src=%u.%u.%u.%u:%u -> dst=%u.%u.%u.%u:%u\n",
552	           (unsigned)frame.size(),
553	           (info.ipv4_src_addr >> 24) & 0xFF, (info.ipv4_src_addr >> 16) & 0xFF,
554	           (info.ipv4_src_addr >> 8) & 0xFF, info.ipv4_src_addr & 0xFF,
555	           info.udp_src_port,
556	           (ctx->local_ip >> 24) & 0xFF, (ctx->local_ip >> 16) & 0xFF,
557	           (ctx->local_ip >> 8) & 0xFF, ctx->local_ip & 0xFF,
558	           info.udp_dst_port);
559	
560	    uint32_t ts_sec  = (uint32_t)(ts_ns_start / 1000000000ull);
561	    uint32_t ts_frac = (uint32_t)(ts_ns_start % 1000000000ull);
562	    ctx->writer.write(ts_sec, ts_frac, frame);
563	
564	    if (ctx->merge_logger && ctx->merge_logger->enabled()) {
565	        ctx->merge_logger->log(ts_ns_start, frame);
566	    }
567	}
568	
569	} // namespace pcapreplay
