39	// Description: Minimal C++ helper for reading/writing PCAP files in the
40	//              system-level VProc testbench.
41	//==========================================================================
42	
43	#pragma once
44	
45	#include <cstdint>
46	#include <cstdio>
47	#include <vector>
48	#include <string>
49	
50	namespace pcapio {
51	
52	enum class TimeRes { Micros, Nanos };
53	
54	struct GlobalHdr {
55	   uint32_t magic;
56	   uint16_t ver_major;
57	   uint16_t ver_minor;
58	   int32_t  thiszone;
59	   uint32_t sigfigs;
60	   uint32_t snaplen;
61	   uint32_t network; // 1 = Ethernet
62	};
63	
64	struct RecHdr {
65	   uint32_t ts_sec;
66	   uint32_t ts_frac; // usec or nsec depending on magic
67	   uint32_t incl_len;
68	   uint32_t orig_len;
69	};
70	
71	class Reader {
72	public:
73	   Reader() = default;
74	   ~Reader() { close(); }
75	
76	   bool open(const std::string &path) {
77	      close();
78	      f_ = std::fopen(path.c_str(), "rb");
79	      if (!f_)
80	         return false;
81	      if (std::fread(&gh_, sizeof(gh_), 1, f_) != 1) {
82	         close();
83	         return false;
84	      }
85	      detect_endian_and_res();
86	      return ok_;
87	   }
88	
89	   void close() {
90	      if (f_) {
91	         std::fclose(f_);
92	         f_ = nullptr;
93	      }
94	      ok_ = false;
95	   }
96	
97	   bool good() const { return ok_; }
98	   TimeRes time_res() const { return res_; }
99	
100	   struct Packet { uint32_t ts_sec, ts_frac; std::vector<uint8_t> data; };
101	
102	   bool next(Packet &pkt) {
103	      if (!ok_)
104	         return false;
105	      RecHdr rh{};
106	      if (std::fread(&rh, sizeof(rh), 1, f_) != 1)
107	         return false;
108	      fix_rec_hdr(rh);
109	      pkt.ts_sec  = rh.ts_sec;
110	      pkt.ts_frac = rh.ts_frac;
111	      pkt.data.resize(rh.incl_len);
112	      if (rh.incl_len > 0) {
113	         if (std::fread(pkt.data.data(), 1, rh.incl_len, f_) != rh.incl_len)
114	               return false;
115	      }
116	      return true;
117	   }
118	
119	private:
120	   void detect_endian_and_res() {
121	      // Known magics
122	      // 0xa1b2c3d4  native, micros; 0xd4c3b2a1 swapped, micros
123	      // 0xa1b23c4d  native, nanos;  0x4d3cb2a1 swapped, nanos
124	      ok_ = true;
125	      swap_ = false;
126	      res_ = TimeRes::Micros;
127	      switch (gh_.magic) {
128	         case 0xa1b2c3d4:
129	            swap_ = false;
130	            res_ = TimeRes::Micros;
131	            break;
132	         case 0xd4c3b2a1:
133	            swap_ = true;
134	            res_ = TimeRes::Micros;
135	            break;
136	         case 0xa1b23c4d:
137	            swap_ = false;
138	            res_ = TimeRes::Nanos;
139	            break;
140	         case 0x4d3cb2a1:
141	            swap_ = true;
142	            res_ = TimeRes::Nanos;
143	            break;
144	         default:
145	            ok_ = false;
146	            break;
147	      }
148	      if (swap_)
149	      {
150	         swap_global();
151	      }
152	      if (gh_.network != 1) {
153	         // Not Ethernet; still allow but warn via ok_ flag if desired.
154	      }
155	   }
156	
157	   static uint16_t bswap16(uint16_t v) {
158	      return (uint16_t)((v>>8) | (v<<8));
159	   }
160	   static uint32_t bswap32(uint32_t v) {
161	      return (v>>24) | ((v>>8)&0x0000FF00) | ((v<<8)&0x00FF0000) | (v<<24);
162	   }
163	
164	   void swap_global() {
165	      gh_.magic     = bswap32(gh_.magic);
166	      gh_.ver_major = bswap16(gh_.ver_major);
167	      gh_.ver_minor = bswap16(gh_.ver_minor);
168	      gh_.thiszone  = (int32_t)bswap32((uint32_t)gh_.thiszone);
169	      gh_.sigfigs   = bswap32(gh_.sigfigs);
170	      gh_.snaplen   = bswap32(gh_.snaplen);
171	      gh_.network   = bswap32(gh_.network);
172	   }
173	
174	   void fix_rec_hdr(RecHdr &rh) const {
175	      if (!swap_)
176	         return;
177	      rh.ts_sec  = bswap32(rh.ts_sec);
178	      rh.ts_frac = bswap32(rh.ts_frac);
179	      rh.incl_len= bswap32(rh.incl_len);
180	      rh.orig_len= bswap32(rh.orig_len);
181	   }
182	
183	   FILE     *f_ = nullptr;
184	   GlobalHdr gh_{};
185	   bool      ok_ = false;
186	   bool      swap_ = false;
187	   TimeRes   res_ = TimeRes::Micros;
188	};
189	
190	class Writer {
191	public:
192	   Writer() = default;
193	   ~Writer() { close(); }
194	
195	   bool open(const std::string &path, TimeRes res = TimeRes::Nanos, uint32_t snaplen = 0x00040000) {
196	      close();
197	      f_ = std::fopen(path.c_str(), "wb");
198	      if (!f_)
199	         return false;
200	      res_ = res;
201	      GlobalHdr gh{};
202	      gh.magic     = (res == TimeRes::Nanos) ? 0xa1b23c4d : 0xa1b2c3d4; // little-endian
203	      gh.ver_major = 2;
204	      gh.ver_minor = 4;
205	      gh.thiszone  = 0;
206	      gh.sigfigs   = 0;
207	      gh.snaplen   = snaplen;
208	      gh.network   = 1; // Ethernet
209	      if (std::fwrite(&gh, sizeof(gh), 1, f_) != 1) {
210	         close();
211	         return false;
212	      }
213	      ok_ = true;
214	      return true;
215	   }
216	
217	   void close() {
218	      if (f_) { std::fclose(f_); f_ = nullptr; }
219	      ok_ = false;
220	   }
221	
222	   bool good() const {
223	      return ok_;
224	   }
225	   TimeRes time_res() const {
226	      return res_;
227	   }
228	
229	   bool write(uint32_t ts_sec, uint32_t ts_frac, const uint8_t* data, uint32_t len) {
230	      if (!ok_)
231	         return false;
232	      RecHdr rh { ts_sec, ts_frac, len, len };
233	      if (std::fwrite(&rh, sizeof(rh), 1, f_) != 1)
234	         return false;
235	      if (len && std::fwrite(data, 1, len, f_) != len)
236	         return false;
237	      std::fflush(f_);
238	      return true;
239	   }
240	
241	   bool write(uint32_t ts_sec, uint32_t ts_frac, const std::vector<uint8_t> &data) {
242	      return write(ts_sec, ts_frac, data.data(), (uint32_t)data.size());
243	   }
244	
245	private:
246	   FILE   *f_ = nullptr;
247	   bool    ok_ = false;
248	   TimeRes res_ = TimeRes::Nanos;
249	};
250	
251	} // namespace pcapio
